window.REC_META = {"repo": "mega-free-chat", "subtitle": "Descubrir el pool, ordenar, rotar y transmitir por SSE", "description": "Una pasarela FastAPI que descubre los modelos gratuitos de OpenRouter, mantiene su estado en memoria, los ordena con prioridad a proveedores chinos y transmite la respuesta por Server-Sent Events. Incluye el límite real del generador perezoso.", "repo_url": "https://github.com/wanderc137/mega-free-chat", "page_url": "https://wanderc137.github.io/mega-free-chat/", "poster_text": "Una pasarela FastAPI que descubre los modelos gratuitos de OpenRouter, mantiene su estado en memoria, los ordena con prioridad a proveedores chinos y transmite la respuesta por Server-Sent Events. Incluye el límite real del generador perezoso.", "commands": ["./run.sh", "curl -s http://localhost:8000/api/models", "curl -N -X POST http://localhost:8000/api/chat -H 'Content-Type: application/json' -d '{\"message\":\"hola\"}'"], "chapters": [{"time": "0:06", "label": "EL PROBLEMA", "title": "El catálogo gratuito cambia sin avisar"}, {"time": "0:24", "label": "ARQUITECTURA", "title": "Tres objetos y un contrato de entrada"}, {"time": "0:40", "label": "DESCUBRIR EL POOL", "title": "Precio cero, pero también modelo de chat"}, {"time": "0:57", "label": "ESTADO Y COOLDOWN", "title": "Un modelo que falla no se reintenta en cada mensaje"}, {"time": "1:13", "label": "ORDEN", "title": "Prioridad a proveedores chinos, luego orden estable"}, {"time": "1:28", "label": "FAILOVER", "title": "Probar el siguiente, marcar el fallo y no rendirse en silencio"}, {"time": "1:46", "label": "EL CLIENTE", "title": "Un generador de fragmentos, no una respuesta completa"}, {"time": "2:03", "label": "EL LÍMITE DOCUMENTADO", "title": "El failover no atrapa el error del primer token"}, {"time": "2:22", "label": "SSE", "title": "Cuatro eventos y headers que evitan el buffer"}, {"time": "2:37", "label": "LA UI", "title": "Parsear SSE a mano, sin librerías"}, {"time": "2:55", "label": "CÓMO EJECUTARLO", "title": "Un script, un puerto y dos endpoints para probar"}], "width": 104, "height": 34, "duration": 201.45, "title": "Mega Free Chat · failover entre modelos de $0"};
